// Safeguard marker: INSTAOPS_V2_RECOVERY — supports CHECK_CONNECTIONS, strict Meta Graph VERIFY_PUBLICATION (no list[0] fallback), and SAFE_RETRY.
function readCfg(key, fallback) {
  var blocked = false;
  try { if (typeof $vars !== 'undefined' && $vars && $vars[key] !== undefined && $vars[key] !== null && $vars[key] !== '') return { value: String($vars[key]), source: 'vars', blocked: false }; } catch (_) {}
