return [{ json: { ok: true, services: { supabase: supabase, sheets: sheets, cloudinary: cloudinary, instagram: instagram, n8nEnv: req.n8nEnv } } }];

var req = $('CODE | Validate Recovery Operation').first().json;
var raw = $input.first().json || {};
var body = raw.body !== undefined ? raw.body : raw;
var row = Array.isArray(body) ? body[0] : body;
if (!row || !row.id) {
