if (res === 'MARK_PUBLISHED' || res === 'CHECK_EXECUTION') {
  return [{ json: { mode: 'VERIFY_PROVIDER', row: row, dest_ig_user_id: String(row.ig_user_id || req.ig_user_id), candidate_id: String(req.published_id || row.published_id || '').trim(), container_id: String(req.container_id || row.container_id || '').trim() } }];
}
if (row.status === 'PUBLISHED' || (row.published_id && String(row.published_id).trim() !== '')) {
