var acctU = unpack($('HTTP | Read Destination Account').first().json);
var acct = Array.isArray(acctU.body) ? acctU.body[0] : acctU.body;
var igAcctU = unpack($('HTTP | Graph Verify Destination Account Identity').first().json);
var medU = unpack($('HTTP | Graph Verify Candidate Media').first().json);
