if (!verified) {
  var why = !acctOk ? 'Destination account verification failed' : dupConflict ? 'published_id already belongs to a different post' : !ownerMatch || !usernameMatch ? 'Media owner does not match destination Instagram account' : !typeOk ? 'Media type mismatch with target post' : 'Meta Graph API could not verify candidate published_id; retaining VERIFY_MANUALLY.';
  return [{ json: { verified: false, row: row, result: { ok: true, verified: false, post_uuid: row.id, post_id: row.post_id, status: 'VERIFY_MANUALLY', error: why } } }];
}
return [{ json: { verified: true, row: row, verified_id: String(mb.id), verified_url: String(mb.permalink || '') } }];

